-- Bowmasters(AU)[32+64]-v15.01--Nobita
-- Khong sua file nay. Moi thay doi lam hong bo giai ma.
local _zceqig = 96
local _tauojh = 224
local _zqnkvk = 43
local _lgqrki = ""

local _sueqsh = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _tnozel(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _vhfoat(d)
	d = d:gsub("[^" .. _sueqsh .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_sueqsh:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _npgwfp = _vhfoat(_lgqrki)
local _ersmwp = { _zceqig, _tauojh, _zqnkvk }
local _kayeeb = {}
for i = 1, #_npgwfp do
	_kayeeb[i] = string.char(_tnozel(_npgwfp:byte(i), _ersmwp[(i - 1) % 3 + 1]))
end

local _kgqrbd = load or loadstring
local _vgvoit, _lpcxcr = _kgqrbd(table.concat(_kayeeb), "=w")
if not _vgvoit then
	gg.alert("File hong: " .. tostring(_lpcxcr))
	os.exit()
end
_vgvoit()
